package com.casecraft.model;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="statements") public class Statement { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="case_id",nullable=false) private CaseFile caseFile; private String speaker; @Column(length=5000) private String content; private LocalDateTime recordedAt=LocalDateTime.now(); public UUID getId(){return id;} public CaseFile getCaseFile(){return caseFile;} public void setCaseFile(CaseFile c){caseFile=c;} public String getSpeaker(){return speaker;} public void setSpeaker(String v){speaker=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public LocalDateTime getRecordedAt(){return recordedAt;} }
